solve:{[tokens;codes]
  rnd:{[x;p] scale:10f xexp p;t:x*scale;low:floor t;low+:1*((t-low)>0.5)|(((t-low)=0.5)&(1=low mod 2));low%scale};
  norm:{lower x};effective:"";longs:();floats:();bools:();chars:();syms:();symidx:();recast:0;i:0;
  while[i<count tokens;t:tokens i;decl:codes i;ok:0;attempt:enlist decl;
    if[not attempt~enlist `$codes;attempt,:?"jfbcs";attempt,:attempt where not attempt~enlist `$codes];
    j:0;while[(j<count attempt)&not ok;code:attempt j;
      case code~`j:if[(t in (enlist "-"),string til 1000000000);v:"J"$t;effective,:enlist "j";longs,:v;ok:1];
      case code~`f:if[((t in (enlist "-"),string til 1000000000)|((count t)>1)&((count .?t "x")=1))&
          (((0="F"$t)&t~"0")|((0<abs "F"$t)&(abs "F"$t)<1000000f));
          v:rnd["F"$t;3];effective,:enlist "f";floats,:v;ok:1];
      case code~`b:if[norm t in ("0";"1";"t";"f";"true";"false");
          v:1*(norm t in ("1";"t";"true"));effective,:enlist "b";bools,:v;ok:1];
      case code~`c:if[(1=count t);v:"I"$first t;effective,:enlist "c";chars,:v;ok:1];
      case code~`s:effective,:enlist "s";syms,:enlist t;symidx,:count syms;ok:1];j+:1];
    if[not `$effective~`$enlist decl;recast+:1];i+:1];
  syms:distinct syms;symidx:{[arg0;arg1]arg0?arg1}[syms] each tokens where ("s"=enlist each effective);
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!(effective;longs;floats;bools;chars;syms;symidx;recast;
    rnd[(sum longs)+sum floats+sum bools+sum chars+sum symidx;3])}
