solve:{[tokens;codes]
  rnd:{[x;p] scale:10f xexp p;t:x*scale;low:floor t;low+:1*((t-low)>0.5)|(((t-low)=0.5)&(1=low mod 2));low%scale};
  tryj:{[tok]
    if["-"~first tok;if[not (count tok)=1;if[not all (1_"$")tok in "0123456789";:0n]]];
    v:"J"$tok;if[(abs v)>=1000000000f;:0n];v};
  tryf:{[tok]
    s:tok;dot:count s where "."=s;
    if[(dot>1)|((1=dot)&((first s)=".")&((last s)=".") );:0n];
    if["-"~first s;if[not (count s)=1;if[not all (1_"$")s in "0123456789.";:0n]]];
    v:"F"$tok;if[(abs v)>=1000000f;:0n];rnd[v;3]};
  tryb:{[tok]
    s:lower tok;
    if[(s~"1")|(s~"t")|(s~"true");1b];
    if[(s~"0")|(s~"f")|(s~"false");0b];
    0n};
  tryc:{[tok] if[(count tok)=1;first tok];0n};
  longs:();floats:();bools:();chars:();syms:();symidx:();effective:"";recast:0;i:0;
  while[i<count tokens;tok:tokens i;code:`$codes i;value:0n;eff:code;
    if[not null value:try code tok;
      j:0;while[j<count `j`f`b`c`s;if[not (`$string (code`j`f`b`c`s) j)~code;
        value:try (`j`f`b`c`s) j tok;
        if[not null value;eff:`j`f`b`c`s j;break]];j+:1]];
    if[eff~`j;longs,:value];
    if[eff~`f;floats,:value];
    if[eff~`b;bools,:value];
    if[eff~`c;chars,:value];
    if[eff~`s;
      ix:first where syms~enlist tok;
      if[ix=count syms;syms,:enlist tok];symidx,:ix];
    effective,:string eff;
    if[not eff~code;recast+:1];i+:1];
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!(
    effective;longs;floats;bools;chars;syms;symidx;recast;
    rnd[(sum longs)+sum floats+sum bools+sum chars+sum symidx;3])}
